"""Closed-loop insertion controller for ALOHA-2 #1 (vision + force servo)."""
import json, re, sys, time, math, workcell

def call(*a):
    r = workcell.call("robot", *a)
    return r

def locate():
    r = workcell.call("vision", "locate", "--json")
    t = r.text if isinstance(r.text, str) else ""
    try:
        t = json.loads(t)["text"]
    except Exception:
        pass
    out = {}
    m = re.search(r"socket hole centre: x=([-\d.]+) y=([-\d.]+) mm, top at z=([-\d.]+)", t)
    if m: out["hole"] = tuple(map(float, m.groups()))
    m = re.search(r"cap: centre x=([-\d.]+) y=([-\d.]+) z=([-\d.]+)", t)
    out["cap"] = tuple(map(float, m.groups())) if m else None
